import { GaugeAdapter } from '@dreadnought/react/unstyled';
const thresholds = [{ id: 'normal', label: 'Норма', to: 60 }, { id: 'warning', label: 'Внимание', to: 80 }, { id: 'critical', label: 'Критично', to: 100 }];
export function Example() { return <GaugeAdapter value={72} label="Загрузка сервера" thresholds={thresholds} formatValue={value => `${value}%`} />; }
